import type { MetadataRoute } from "next";
import { getSiteBaseUrl } from "@/lib/site-url";

export default function robots(): MetadataRoute.Robots {
  const base = getSiteBaseUrl().origin;
  return {
    rules: {
      userAgent: "*",
      allow: "/",
      disallow: ["/admin", "/admin/"],
    },
    sitemap: `${base}/sitemap.xml`,
  };
}

import type { MetadataRoute } from "next";
import { getSiteBaseUrl } from "@/lib/site-url";

/** Public customer routes (no private order tokens). */
const PATHS: { path: string; changeFrequency: MetadataRoute.Sitemap[0]["changeFrequency"]; priority: number }[] =
  [
    { path: "/", changeFrequency: "daily", priority: 1 },
    { path: "/checkout", changeFrequency: "weekly", priority: 0.8 },
    { path: "/my-order", changeFrequency: "weekly", priority: 0.7 },
    { path: "/privacy", changeFrequency: "monthly", priority: 0.4 },
    { path: "/newsletter", changeFrequency: "monthly", priority: 0.4 },
  ];

export default function sitemap(): MetadataRoute.Sitemap {
  const base = getSiteBaseUrl().origin;
  const lastModified = new Date();
  return PATHS.map(({ path, changeFrequency, priority }) => ({
    url: `${base}${path}`,
    lastModified,
    changeFrequency,
    priority,
  }));
}

